+/// One recorded exception pulled from a county recorder export: a lien,
+/// an easement, a CC&R — anything that encumbers title.
+///
+/// Classification is deliberately NOT part of this: lien vs easement vs
+/// covenant is a judgment we keep getting wrong automatically, so it needs
+/// its own review pass and a visible "uncategorized" state instead.
+class TitleException {
+  const TitleException({
+    required this.id,
+    required this.countyRecord,
+    required this.instrument,
+    required this.recordedAt,
+    this.category = ExceptionCategory.uncategorized,
+  });
+
+  final String id;
+  final String countyRecord;
+  final String instrument;
+  final DateTime recordedAt;
+  final ExceptionCategory category;
+}

